public int Jump(int[] nums)
{
    int n = nums.Length;
    if (n <= 1) return 0;

    int jumps = 0;
    int currentLayerEnd = 0;   // last index reachable with 'jumps' jumps
    int farthestReach = 0;     // farthest index reachable with 'jumps + 1' jumps

    for (int i = 0; i < n - 1; i++)
    {
        farthestReach = Math.Max(farthestReach, i + nums[i]);

        // We have exhausted every position reachable in the current number of jumps
        if (i == currentLayerEnd)
        {
            jumps++;
            currentLayerEnd = farthestReach;

            if (currentLayerEnd >= n - 1) break;
        }
    }

    return jumps;
}

public int JumpDp(int[] nums)
{
    int n = nums.Length;
    var dp = new int[n];
    Array.Fill(dp, int.MaxValue);
    dp[0] = 0;

    for (int i = 0; i < n; i++)
    {
        for (int j = i + 1; j <= Math.Min(n - 1, i + nums[i]); j++)
        {
            dp[j] = Math.Min(dp[j], dp[i] + 1);
        }
    }

    return dp[n - 1];
}

public int Jump(int[] nums)
{
    int jumps = 0, currentLayerEnd = 0, farthestReach = 0;

    for (int i = 0; i < nums.Length - 1; i++)
    {
        farthestReach = Math.Max(farthestReach, i + nums[i]);
        if (i == currentLayerEnd)
        {
            jumps++;
            currentLayerEnd = farthestReach;
        }
    }

    return jumps;
}
